// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }
    function testRegression_property() public {
        uint256 initialSupply = c.totalSupply();

        bool success = false;
        try c.XBornID() {
            success = true;
        } catch {
            success = false;
        }

        c = new XBORNID();

        uint256 supplyBefore = c.totalSupply();

        bool xbornSuccess = false;
        try c.XBornID() {
            xbornSuccess = true;
        } catch {
            xbornSuccess = false;
        }

        bool burnSuccess = false;
        try c.burn(1e18) {
            burnSuccess = true;
        } catch {
            burnSuccess = false;
        }

        uint256 supplyAfter = c.totalSupply();

        assertTrue(supplyAfter != supplyBefore, "totalSupply should change after burn");
    }
}
